export const noteSlice = createSlice({
  name: '@@app/note',
  initialState,
  reducers: {
    addNote(state, action: PayloadAction<Note>) {
      state.notes[action.payload.id] = action.payload
    },
    updateNote(state, action: PayloadAction<Note>) {
      state.notes[action.payload.id] = action.payload
    },
    deleteNote(state, action: PayloadAction<string>) {
      delete state.notes[action.payload]
    },
    trashNote(state, action: PayloadAction<string>) {
      const note = state.notes[action.payload]
      if (note) {
        note.trash = true
      }
    },
    restoreNote(state, action: PayloadAction<string>) {
      const note = state.notes[action.payload]
      if (note) {
        note.trash = false
      }
    },
    permanentlyDeleteNote(state, action: PayloadAction<string>) {
      delete state.notes[action.payload]
    },
    emptyTrash(state) {
      Object.values(state.notes)
        .filter(note => note.trash)
        .forEach(note => {
          delete state.notes[note.id]
        })
    },
